from __future__ import annotations
from pathlib import Path
import base64, io, tarfile

ARCHIVE_SHA256 = "f715f3b62ca56bb87d46170ba9a2f3ef2aa426435cd355aa4fc70279ece4a4d5"
_ARCHIVE_B64 = ""

def materialize(destination: str|Path|None=None):
    dest=Path(destination) if destination else Path(__file__).resolve().parent
    dest.mkdir(parents=True,exist_ok=True)
    raw=base64.b64decode(_ARCHIVE_B64)
    import hashlib
    if hashlib.sha256(raw).hexdigest()!=ARCHIVE_SHA256:
        raise RuntimeError("R22 embedded archive digest mismatch")
    with tarfile.open(fileobj=io.BytesIO(raw),mode="r:gz") as tf:
        tf.extractall(dest)
    return [str(dest/name) for name in (
        "FOUNDRY_OPERATIONAL_CORPUS_R22.json",
        "FOUNDRY_WORK_QUEUE_R22.json",
        "FOUNDRY_HR_TOPOLOGY_R22.json",
        "FOUNDRY_SERVER_TOPOLOGY_R22.json",
    )]

if __name__=="__main__":
    for p in materialize(): print(p)
